<?php require_once __DIR__ . '/includes/config.php';role(['admin','hr','payroll','auditor']);$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){check();$p->prepare('UPDATE investigations SET status=?,review_notes=?,reviewed_by=?,reviewed_at=NOW() WHERE id=?')->execute([$_POST['status'],$_POST['review_notes'],$_SESSION['user']['id'],$_POST['id']]);log_action('REVIEW_INVESTIGATION','ID '.$_POST['id']);$_SESSION['flash']='Review updated';header('Location:investigations.php');exit;}$rows=$p->query('SELECT i.*,p.employee_no,p.pay_period,p.gross_amount,e.full_name FROM investigations i JOIN payroll p ON p.id=i.payroll_id LEFT JOIN employees e ON e.id=i.employee_id ORDER BY i.id DESC')->fetchAll();head('Investigations');?><h1>Investigations</h1><p><a class="button" href="detect.php">Run detection again</a></p><?php foreach($rows as $r):?><section class="panel"><h3><?=e($r['employee_no'])?> — <?=e($r['full_name']??'Unmatched')?></h3><p><?=e($r['reason'])?> · <?=e($r['pay_period'])?> · <?=number_format($r['gross_amount'],2)?></p><form method="post" class="grid"><input type="hidden" name="token" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><label>Status<select name="status"><?php foreach(['pending','under_review','cleared','confirmed_issue'] as $v):?><option <?=$r['status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Review notes<input name="review_notes" value="<?=e($r['review_notes'])?>"></label><button>Save review</button></form></section><?php endforeach;?><?php if(!$rows)echo '<p>No flags yet. Run detection.</p>';foot();?>